<section class="section-heading reveal"><div><h2>Услуги</h2><p>Справочник услуг для продаж из карточки курсанта.</p></div></section>
<section class="finance-admin-grid">
    <article class="panel reveal"><div class="panel__header"><div><p class="page-eyebrow">Новая услуга</p><h3>Добавить услугу</h3></div></div><form method="post" action="<?= e(url('/education/services')) ?>" class="stacked-form"><?= csrf_field() ?><label class="field"><span class="field__label">Название</span><span class="field__control"><input name="name" required maxlength="190" placeholder="Курс категории B"></span></label><label class="field"><span class="field__label">Стоимость</span><span class="field__control"><input type="text" name="price" required inputmode="decimal" autocomplete="off" placeholder="0,00" data-money-input></span></label><label class="field"><span class="field__label">Описание</span><span class="field__control"><textarea name="description" rows="3"></textarea></span></label><input type="hidden" name="status" value="active"><button class="button button--primary" type="submit">Добавить услугу</button></form></article>
    <div class="service-list"><?php foreach ($services as $service): ?><article class="panel reveal service-card"><div><span class="status-pill status-pill--<?= $service['status'] === 'active' ? 'active' : 'blocked' ?>"><i></i><?= $service['status'] === 'active' ? 'Действует' : 'Отключена' ?></span><h3><?= e($service['name']) ?></h3><p><?= e($service['description'] ?: 'Без описания') ?></p></div><strong><?= e(number_format((float) $service['price'], 2, ',', ' ')) ?> ₽</strong><details class="embedded-form"><summary>Изменить</summary><form method="post" action="<?= e(url('/education/services/' . $service['id'] . '/update')) ?>" class="inline-create-form"><?= csrf_field() ?><input name="name" value="<?= e($service['name']) ?>" required><input type="number" name="price" value="<?= e($service['price']) ?>" min="0" step="0.01" required><input name="description" value="<?= e($service['description']) ?>"><select name="status"><option value="active" <?= $service['status'] === 'active' ? 'selected' : '' ?>>Действует</option><option value="inactive" <?= $service['status'] === 'inactive' ? 'selected' : '' ?>>Отключена</option></select><button class="button button--secondary" type="submit">Сохранить</button></form></details></article><?php endforeach; ?><?php if (!$services): ?><div class="panel empty-state"><span><?= icon('file', 28) ?></span><h3>Услуг пока нет</h3><p>Создайте услугу, чтобы продавать её курсантам.</p></div><?php endif; ?></div>
</section>
